/* @lc app=leetcode id=4059 lang=kotlin */ class Solution { fun go(lst: List<Int>, i: Int, res: IntArray, done: IntArray): Unit = if (i == 15) Unit else if (done[i] == 1) go(lst, i + 1, res, done) else lst.partition { (it shr (14 - i)) and 1 == 1 }.let { (t, f) -> (if (t.isEmpty()) Unit else res.set(i, res[i] + t.size).also { go(t, i + 1, res, done) }).also { if (f.isNotEmpty()) done.set(i, 1).also { go(f, i + 1, res, done) } } } fun largestPower(nums: IntArray): IntArray = IntArray(15).also { res -> go(nums.toList(), 0, res, IntArray(15)) } }